29	/// Collects all elements of the flow into prepared children. These are much
30	/// simpler to handle than the raw elements.
31	#[typst_macros::time]
32	pub fn collect<'a>(
33	    engine: &mut Engine,
34	    bump: &'a Bump,
35	    children: &[Pair<'a>],
36	    locator: Locator<'a>,
37	    base: Size,
38	    expand: bool,
39	    mode: FlowMode,
40	) -> SourceResult<Vec<Child<'a>>> {
41	    Collector {
42	        engine,
43	        bump,
44	        locator: locator.split(),
45	        base,
46	        expand,
47	        output: Vec::with_capacity(children.len()),
48	        par_situation: ParSituation::First,
49	    }
50	    .run(children, mode)
51	}
