53	/// State for collection.
54	struct Collector<'a, 'x, 'y> {
55	    engine: &'x mut Engine<'y>,
56	    bump: &'a Bump,
57	    base: Size,
58	    expand: bool,
59	    locator: SplitLocator<'a>,
60	    output: Vec<Child<'a>>,
61	    par_situation: ParSituation,
62	}
63	
64	impl<'a> Collector<'a, '_, '_> {
65	    /// Perform the collection.
66	    fn run(
67	        mut self,
68	        children: &[Pair<'a>],
69	        mode: FlowMode,
70	    ) -> SourceResult<Vec<Child<'a>>> {
71	        // Extract leading and trailing tags.
72	        let (start, end) = children.split_prefix_suffix(|(c, _)| c.is::<TagElem>());
73	        let inner = &children[start..end];
74	
75	        for (c, _) in &children[..start] {
76	            let elem = c.to_packed::<TagElem>().unwrap();
77	            self.output.push(Child::Tag(&elem.tag));
78	        }
79	
80	        match mode {
81	            FlowMode::Root | FlowMode::Block => self.run_block(inner)?,
82	            FlowMode::Inline => self.run_inline(inner)?,
83	        }
84	
85	        for (c, _) in &children[end..] {
86	            let elem = c.to_packed::<TagElem>().unwrap();
87	            self.output.push(Child::Tag(&elem.tag));
88	        }
89	
90	        Ok(self.output)
91	    }
92	
93	    /// Perform collection for block-level children.
94	    fn run_block(&mut self, children: &[Pair<'a>]) -> SourceResult<()> {
95	        for &(child, styles) in children {
96	            if let Some(elem) = child.to_packed::<TagElem>() {
97	                self.output.push(Child::Tag(&elem.tag));
98	            } else if let Some(elem) = child.to_packed::<VElem>() {
99	                self.v(elem, styles);
100	            } else if let Some(elem) = child.to_packed::<ParElem>() {
101	                self.par(elem, styles)?;
102	            } else if let Some(elem) = child.to_packed::<BlockElem>() {
103	                let alone = children.len() == 1;
104	                self.block(elem, styles, alone);
105	            } else if let Some(elem) = child.to_packed::<PlaceElem>() {
106	                self.place(elem, styles)?;
107	            } else if child.is::<FlushElem>() {
108	                self.output.push(Child::Flush);
109	            } else if let Some(elem) = child.to_packed::<ColbreakElem>() {
110	                self.output.push(Child::Break(elem.weak.get(styles)));
111	                self.par_situation = ParSituation::First;
112	            } else if child.is::<PagebreakElem>() {
113	                bail!(
114	                    child.span(), "pagebreaks are not allowed inside of containers";
115	                    hint: "try using a `#colbreak()` instead";
116	                );
117	            } else {
118	                self.engine.sink.warn(warning!(
119	                    child.span(),
120	                    "{} was ignored during paged export",
121	                    child.func().name(),
122	                ));
123	            }
124	        }
125	        Ok(())
126	    }
127	
128	    /// Perform collection for inline-level children.
129	    fn run_inline(&mut self, children: &[Pair<'a>]) -> SourceResult<()> {
130	        // Compute the shared styles.
131	        let styles = StyleChain::trunk_from_pairs(children).unwrap_or_default();
132	
133	        // Layout the lines.
134	        let lines = crate::inline::layout_inline(
135	            self.engine,
136	            children,
137	            &mut self.locator,
138	            styles,
139	            self.base,
140	            self.expand,
141	        )?
142	        .into_frames();
143	
144	        let leading = styles.resolve(ParElem::leading);
145	        self.lines(lines, leading, styles);
146	
147	        Ok(())
148	    }
149	
150	    /// Collect vertical spacing into a relative or fractional child.
151	    fn v(&mut self, elem: &'a Packed<VElem>, styles: StyleChain<'a>) {
152	        self.output.push(match elem.amount {
153	            Spacing::Rel(rel) => {
154	                Child::Rel(rel.resolve(styles), elem.weak.get(styles) as u8)
155	            }
156	            Spacing::Fr(fr) => Child::Fr(fr, elem.weak.get(styles) as u8),
157	        });

