33	/// Similar to a [`StackChild`], but with an additional variant that allows
34	/// specifying a custom layouter for a child. Useful when using stack layout to
35	/// create other layouters, such as that of lists.
36	pub enum StackLayoutChild<'a, F>
37	where
38	    F: Fn(&mut Engine, StyleChain, Regions) -> SourceResult<Fragment>,
39	{
40	    /// A stack child with content or spacing.
41	    StackChild(&'a StackChild),
42	    /// A child with a custom layouter, producing its own frames.
43	    CustomLayouter(F),
44	}
45	
46	impl<'a, F> From<&'a StackChild> for StackLayoutChild<'a, F>
47	where
48	    F: Fn(&mut Engine, StyleChain, Regions) -> SourceResult<Fragment>,
49	{
50	    fn from(value: &'a StackChild) -> Self {
51	        Self::StackChild(value)
52	    }
53	}
54	
55	/// Layout multiple cells like a stack. Requires only the spacing to insert
56	/// between blocks, the stack growth direction, its children, as well as
57	/// relevant layout information.
58	///
59	/// In particular, this doesn't require creating a stack element explicitly, as
60	/// it requires `Content`, which has restrictions as to which values it can
61	/// hold. In particular, elements, even if internal, cannot contain
62	/// borrows/lifetime generics, even though they can have custom layout
63	/// procedures. Therefore, calling this function allows customizing stack layout
64	/// more deeply, such as for lists, which need a custom layout function that
65	/// might borrow data from the environment for each list item (a stack child).
66	/// Each child receives relevant layout data from the stack as well.
67	#[expect(clippy::too_many_arguments)]
68	pub fn layout_stack_internal<'a, F>(
69	    children: impl IntoIterator<Item = StackLayoutChild<'a, F>>,
70	    span: Span,
71	    spacing: Option<Spacing>,
72	    dir: Dir,
73	    engine: &mut Engine,
74	    locator: Locator,
75	    styles: StyleChain,
76	    regions: Regions,
77	) -> SourceResult<Fragment>
78	where
79	    F: Fn(&mut Engine, StyleChain, Regions) -> SourceResult<Fragment>,
80	{
81	    let mut layouter = StackLayouter::new(span, dir, locator, styles, regions);
82	    let axis = layouter.dir.axis();
83	    let mut deferred = None;
84	
85	    for child in children {
86	        match child {
87	            StackLayoutChild::StackChild(StackChild::Spacing(kind)) => {
88	                layouter.layout_spacing(*kind);
89	                deferred = None;
90	            }
91	            StackLayoutChild::StackChild(StackChild::Block(block)) => {
92	                // Transparently handle `h`.
93	                if let (Axis::X, Some(h)) = (axis, block.to_packed::<HElem>()) {
94	                    layouter.layout_spacing(h.amount);
95	                    deferred = None;
96	                    continue;
97	                }
98	
99	                // Transparently handle `v`.
100	                if let (Axis::Y, Some(v)) = (axis, block.to_packed::<VElem>()) {
101	                    layouter.layout_spacing(v.amount);
102	                    deferred = None;
103	                    continue;
104	                }
105	
106	                if let Some(kind) = deferred {
107	                    layouter.layout_spacing(kind);
108	                }
109	
110	                layouter.layout_block(engine, block, styles)?;
111	                deferred = spacing;
112	            }
113	            StackLayoutChild::CustomLayouter(custom_layouter) => {
114	                if let Some(kind) = deferred {
115	                    layouter.layout_spacing(kind);
116	                }
117	
118	                layouter.layout_custom_layouter(engine, custom_layouter, styles)?;
119	                deferred = spacing;
120	            }
121	        }
122	    }
123	
124	    layouter.finish()
125	}
126	
127	/// Performs stack layout.
128	struct StackLayouter<'a> {
129	    /// The span to raise errors at during layout.
130	    span: Span,
131	    /// The stacking direction.
132	    dir: Dir,
133	    /// The axis of the stacking direction.
134	    axis: Axis,
135	    /// Provides unique locations to the stack's children.
136	    locator: SplitLocator<'a>,
137	    /// The inherited styles.
138	    styles: StyleChain<'a>,
139	    /// The regions to layout children into.
140	    regions: Regions<'a>,
141	    /// Whether the stack itself should expand to fill the region.
142	    expand: Axes<bool>,
143	    /// The initial size of the current region before we started subtracting.
144	    initial: Size,
145	    /// The generic size used by the frames for the current region.
146	    used: GenericSize<Abs>,
147	    /// The sum of fractions in the current region.
148	    fr: Fr,
149	    /// Already layouted items whose exact positions are not yet known due to
150	    /// fractional spacing.
151	    items: Vec<StackItem>,
152	    /// Finished frames for previous regions.
153	    finished: Vec<Frame>,
154	}
155	
156	/// A prepared item in a stack layout.
157	enum StackItem {
158	    /// Absolute spacing between other items.
159	    Absolute(Abs),
160	    /// Fractional spacing between other items.
161	    Fractional(Fr),
162	    /// A frame for a layouted block.
163	    Frame(Frame, Axes<FixedAlignment>),
164	}
165	
166	impl<'a> StackLayouter<'a> {
167	    /// Create a new stack layouter.
168	    fn new(
169	        span: Span,
170	        dir: Dir,
171	        locator: Locator<'a>,
172	        styles: StyleChain<'a>,
173	        mut regions: Regions<'a>,
174	    ) -> Self {
175	        let axis = dir.axis();
176	        let expand = regions.expand;
177	
178	        // Disable expansion along the block axis for children.
179	        regions.expand.set(axis, false);
180	
181	        Self {
182	            span,
183	            dir,
184	            axis,
185	            locator: locator.split(),
186	            styles,
187	            regions,
188	            expand,
189	            initial: regions.size,
190	            used: GenericSize::zero(),
191	            fr: Fr::zero(),
192	            items: vec![],
193	            finished: vec![],
194	        }
195	    }
196	
197	    /// Add spacing along the spacing direction.
198	    fn layout_spacing(&mut self, spacing: Spacing) {
199	        match spacing {
200	            Spacing::Rel(v) => {
201	                // Resolve the spacing and limit it to the remaining space.
202	                let resolved = v
203	                    .resolve(self.styles)
204	                    .relative_to(self.regions.base().get(self.axis));
205	                let remaining = self.regions.size.get_mut(self.axis);
206	                let limited = resolved.min(*remaining);
207	                if self.dir.axis() == Axis::Y {
208	                    *remaining -= limited;
209	                }
210	                self.used.main += limited;
211	                self.items.push(StackItem::Absolute(resolved));
212	            }
213	            Spacing::Fr(v) => {
214	                self.fr += v;
215	                self.items.push(StackItem::Fractional(v));
216	            }
217	        }
218	    }
219	
220	    /// Layout an arbitrary block.
221	    fn layout_block(
222	        &mut self,
223	        engine: &mut Engine,
224	        block: &Content,
225	        styles: StyleChain,
226	    ) -> SourceResult<()> {
227	        if self.regions.is_full() {
228	            self.finish_region()?;
229	        }
230	
231	        // Block-axis alignment of the `AlignElem` is respected by stacks.
232	        let align = if let Some(align) = block.to_packed::<AlignElem>() {
233	            align.alignment.get(styles)
234	        } else if let Some(styled) = block.to_packed::<StyledElem>() {
235	            styles.chain(&styled.styles).get(AlignElem::alignment)
236	        } else {
237	            styles.get(AlignElem::alignment)
238	        }
239	        .resolve(styles);
240	
241	        let fragment = crate::layout_fragment(
242	            engine,
243	            block,
244	            self.locator.next(&block.span()),
245	            styles,
246	            self.regions,
247	        )?;
248	
249	        self.layout_fragment(align, fragment)
250	    }
251	
252	    /// Layout a child with a custom layouter procedure.
253	    fn layout_custom_layouter(
254	        &mut self,
255	        engine: &mut Engine,
256	        layouter: impl Fn(&mut Engine, StyleChain, Regions) -> SourceResult<Fragment>,
257	        styles: StyleChain,
258	    ) -> SourceResult<()> {
259	        if self.regions.is_full() {
260	            self.finish_region()?;
261	        }
262	
263	        let align = styles.get(AlignElem::alignment).resolve(styles);
264	
265	        let fragment = layouter(engine, styles, self.regions)?;
266	
267	        self.layout_fragment(align, fragment)
268	    }
269	
270	    /// Store laid out content, coming from either a block or a custom layouter.
271	    fn layout_fragment(
272	        &mut self,
273	        align: Axes<FixedAlignment>,
274	        fragment: Fragment,
275	    ) -> SourceResult<()> {
276	        let len = fragment.len();
277	        for (i, frame) in fragment.into_iter().enumerate() {
278	            // Grow our size, shrink the region and save the frame for later.
279	            let specific_size = frame.size();
280	            if self.dir.axis() == Axis::Y {
281	                self.regions.size.y -= specific_size.y;
282	            }
283	
284	            let generic_size = match self.axis {
285	                Axis::X => GenericSize::new(specific_size.y, specific_size.x),
286	                Axis::Y => GenericSize::new(specific_size.x, specific_size.y),
287	            };
288	
289	            self.used.main += generic_size.main;
290	            self.used.cross.set_max(generic_size.cross);
291	
292	            self.items.push(StackItem::Frame(frame, align));
293	
294	            if i + 1 < len {
295	                self.finish_region()?;
296	            }
297	        }
298	
299	        Ok(())
300	    }
301	
302	    /// Advance to the next region.
303	    fn finish_region(&mut self) -> SourceResult<()> {
304	        // Determine the size of the stack in this region depending on whether
305	        // the region expands.
306	        let mut size = self
307	            .expand
308	            .select(self.initial, self.used.into_axes(self.axis))
309	            .min(self.initial);
310	
311	        // Expand fully if there are fr spacings.
312	        let full = self.initial.get(self.axis);
313	        let remaining = full - self.used.main;
314	        if !self.fr.is_zero() && full.is_finite() {
315	            self.used.main = full;
316	            size.set(self.axis, full);
317	        }
318	
319	        if !size.is_finite() {
320	            bail!(self.span, "stack spacing is infinite");
321	        }
322	
323	        let mut output = Frame::soft(size);
324	        let mut cursor = Abs::zero();
325	        let mut ruler: FixedAlignment = self.dir.start().into();
326	
327	        // Place all frames.
328	        for item in self.items.drain(..) {
329	            match item {
330	                StackItem::Absolute(v) => cursor += v,
331	                StackItem::Fractional(v) => cursor += v.share(self.fr, remaining),
332	                StackItem::Frame(frame, align) => {
333	                    if self.dir.is_positive() {
334	                        ruler = ruler.max(align.get(self.axis));
335	                    } else {
