254	/// Builds the pod region for an unbreakable sized container.
255	pub(crate) fn unbreakable_pod(
256	    width: &Sizing,
257	    height: &Sizing,
258	    inset: &Sides<Rel<Abs>>,
259	    styles: StyleChain,
260	    base: Size,
261	) -> Region {
262	    // Resolve the size.
263	    let mut size = Size::new(
264	        match width {
265	            // - For auto, the whole region is available.
266	            // - Fr is handled outside and already factored into the `region`,
267	            //   so we can treat it equivalently to 100%.
268	            Sizing::Auto | Sizing::Fr(_) => base.x,
269	            // Resolve the relative sizing.
270	            Sizing::Rel(rel) => rel.resolve(styles).relative_to(base.x),
271	        },
272	        match height {
273	            Sizing::Auto | Sizing::Fr(_) => base.y,
274	            Sizing::Rel(rel) => rel.resolve(styles).relative_to(base.y),
275	        },
276	    );
277	
278	    // Take the inset, if any, into account.
279	    if !inset.is_zero() {
280	        size = crate::pad::shrink(size, inset);
281	    }
282	
283	    // If the child is manually, the size is forced and we should enable
284	    // expansion.
285	    let expand = Axes::new(
286	        *width != Sizing::Auto && size.x.is_finite(),
287	        *height != Sizing::Auto && size.y.is_finite(),
288	    );
289	
290	    Region::new(size, expand)
291	}
