293	/// Builds the pod regions for a breakable sized container.
294	fn breakable_pod<'a>(
295	    width: &Sizing,
296	    height: &Sizing,
297	    inset: &Sides<Rel<Abs>>,
298	    styles: StyleChain,
299	    regions: Regions,
300	    buf: &'a mut SmallVec<[Abs; 2]>,
301	) -> Regions<'a> {
302	    let base = regions.base();
303	
304	    // The vertical region sizes we're about to build.
305	    let first;
306	    let full;
307	    let backlog: &mut [Abs];
308	    let last;
309	
310	    // If the block has a fixed height, things are very different, so we
311	    // handle that case completely separately.
312	    match height {
313	        Sizing::Auto | Sizing::Fr(_) => {
314	            // If the block is automatically sized, we can just inherit the
315	            // regions.
316	            first = regions.size.y;
317	            full = regions.full;
318	            buf.extend_from_slice(regions.backlog);
319	            backlog = buf;
320	            last = regions.last;
321	        }
322	
323	        Sizing::Rel(rel) => {
324	            // Resolve the sizing to a concrete size.
325	            let resolved = rel.resolve(styles).relative_to(base.y);
326	
327	            // Since we're manually sized, the resolved size is the base height.
328	            full = resolved;
329	
330	            // Distribute the fixed height across a start region and a backlog.
331	            (first, backlog) = distribute(resolved, regions, buf);
332	
333	            // If the height is manually sized, we don't want a final repeatable
334	            // region.
335	            last = None;
336	        }
337	    }
338	
339	    // Resolve the horizontal sizing to a concrete width and combine
340	    // `width` and `first` into `size`.
341	    let mut size = Size::new(
342	        match width {
343	            Sizing::Auto | Sizing::Fr(_) => regions.size.x,
344	            Sizing::Rel(rel) => rel.resolve(styles).relative_to(base.x),
345	        },
346	        first,
347	    );
348	
349	    // Take the inset, if any, into account, applying it to the
350	    // individual region components.
351	    let (mut full, mut last) = (full, last);
352	    if !inset.is_zero() {
353	        crate::pad::shrink_multiple(&mut size, &mut full, backlog, &mut last, inset);
354	    }
355	
356	    // If the child is manually, the size is forced and we should enable
357	    // expansion.
358	    let expand = Axes::new(
359	        *width != Sizing::Auto && size.x.is_finite(),
360	        *height != Sizing::Auto && size.y.is_finite(),
361	    );
362	
363	    Regions { size, full, backlog, last, expand }
364	}
365	
366	/// Distribute a fixed height spread over existing regions into a new first
367	/// height and a new backlog.
368	///
369	/// Note that, if the given height fits within the first region, no backlog is
370	/// generated and the first region's height shrinks to fit exactly the given
371	/// height. In particular, negative and zero heights always fit in any region,
372	/// so such heights are always directly returned as the new first region
373	/// height.
374	fn distribute<'a>(
375	    height: Abs,
376	    mut regions: Regions,
377	    buf: &'a mut SmallVec<[Abs; 2]>,
378	) -> (Abs, &'a mut [Abs]) {
379	    // Build new region heights from old regions.
380	    let mut remaining = height;
381	
382	    // Negative and zero heights always fit, so just keep them.
383	    // No backlog is generated.
384	    if remaining <= Abs::zero() {
385	        buf.push(remaining);
386	        return (buf[0], &mut buf[1..]);
387	    }
388	
389	    loop {
390	        // This clamp is safe (min <= max), as 'remaining' won't be negative
391	        // due to the initial check above (on the first iteration) and due to
392	        // stopping on 'remaining.approx_empty()' below (for the second
393	        // iteration onwards).
394	        let limited = regions.size.y.clamp(Abs::zero(), remaining);
395	        buf.push(limited);
396	        remaining -= limited;
397	        if remaining.approx_empty()
398	            || !regions.may_break()
399	            || (!regions.may_progress() && limited.approx_empty())
400	        {
401	            break;
402	        }
403	        regions.next();
404	    }
405	
406	    // If there is still something remaining, apply it to the
407	    // last region (it will overflow, but there's nothing else
408	    // we can do).
409	    if !remaining.approx_empty()
410	        && let Some(last) = buf.last_mut()
411	    {
412	        *last += remaining;
413	    }
414	
415	    // Distribute the heights to the first region and the
416	    // backlog. There is no last region, since the height is
417	    // fixed.
418	    (buf[0], &mut buf[1..])
419	}

