551	/// The spilled remains of a `MultiChild` that broke across two regions.
552	#[derive(Debug, Clone)]
553	pub struct MultiSpill<'a, 'b> {
554	    pub(super) exist_non_empty_frame: bool,
555	    multi: &'b MultiChild<'a>,
556	    first: Abs,
557	    full: Abs,
558	    backlog: Vec<Abs>,
559	    min_backlog_len: usize,
560	}
561	
562	impl MultiSpill<'_, '_> {
563	    /// Build the spill's frames given regions.
564	    pub fn layout(
565	        mut self,
566	        engine: &mut Engine,
567	        regions: Regions,
568	    ) -> SourceResult<(Frame, Option<Self>)> {
569	        // The first region becomes unchangeable and committed to our backlog.
570	        self.backlog.push(regions.size.y);
571	
572	        // The remaining regions are ephemeral and may be replaced.
573	        let mut backlog: Vec<_> =
574	            self.backlog.iter().chain(regions.backlog).copied().collect();
575	
576	        // Remove unnecessary backlog items to prevent it from growing
577	        // unnecessarily, changing the region's hash.
578	        while backlog.len() > self.min_backlog_len
579	            && backlog.last().copied() == regions.last
580	        {
581	            backlog.pop();
582	        }
583	
584	        // Build the pod with the merged regions.
585	        let pod = Regions {
586	            size: Size::new(regions.size.x, self.first),
587	            expand: regions.expand,
588	            full: self.full,
589	            backlog: &backlog,
590	            last: regions.last,
591	        };
592	
593	        // Extract the not-yet-processed frames.
594	        let mut frames = self
595	            .multi
596	            .layout_full(engine, pod)?
597	            .into_iter()
598	            .skip(self.backlog.len());
599	
600	        // Ensure that the backlog never shrinks, so that unwrapping below is at
601	        // least fairly safe. Note that the whole region juggling here is
602	        // fundamentally not ideal: It is a compatibility layer between the old
603	        // (all regions provided upfront) & new (each region provided on-demand,
604	        // like an iterator) layout model. This approach is not 100% correct, as
605	        // in the old model later regions could have an effect on earlier
606	        // frames, but it's the best we can do for now, until the multi
607	        // layouters are refactored to the new model.
608	        self.min_backlog_len = self.min_backlog_len.max(backlog.len());
609	
610	        // Save the first frame.
611	        let frame = frames.next().unwrap();
612	
613	        // If there's more, return a `spill`.
614	        let mut spill = None;
615	        if frames.next().is_some() {
616	            spill = Some(self);
617	        }
618	
619	        Ok((frame, spill))
620	    }
