192	    fn lines(&mut self, lines: Vec<Frame>, leading: Abs, styles: StyleChain<'a>) {
193	        let align = styles.resolve(AlignElem::alignment);
194	        let costs = styles.get(TextElem::costs);
195	
196	        // Determine whether to prevent widow and orphans.
197	        let len = lines.len();
198	        let prevent_orphans =
199	            costs.orphan() > Ratio::zero() && len >= 2 && !lines[1].is_empty();
200	        let prevent_widows =
201	            costs.widow() > Ratio::zero() && len >= 2 && !lines[len - 2].is_empty();
202	        let prevent_all = len == 3 && prevent_orphans && prevent_widows;
203	
204	        // Store the heights of lines at the edges because we'll potentially
205	        // need these later when `lines` is already moved.
206	        let height_at = |i| lines.get(i).map(Frame::height).unwrap_or_default();
207	        let front_1 = height_at(0);
208	        let front_2 = height_at(1);
209	        let back_2 = height_at(len.saturating_sub(2));
210	        let back_1 = height_at(len.saturating_sub(1));
211	
212	        for (i, frame) in lines.into_iter().enumerate() {
213	            if i > 0 {
